from collections import deque

# ============================================================
# Method 1: DFS-Based Topological Sort
# ============================================================
def topo_sort_dfs(graph, n):
    visited = [False] * n
    stack   = []

    def dfs_visit(u):
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                dfs_visit(v)
        stack.append(u)   # push AFTER all descendants

    for i in range(n):
        if not visited[i]:
            dfs_visit(i)

    return stack[::-1]   # reverse = topological order


# ============================================================
# Method 2: Kahn's Algorithm (BFS with in-degree)
# ============================================================
def kahn_topo_sort(graph, n):
    indegree = [0] * n
    for u in range(n):
        for v in graph[u]:
            indegree[v] += 1

    queue = deque()
    for v in range(n):
        if indegree[v] == 0:
            queue.append(v)

    result = []
    while queue:
        u = queue.popleft()
        result.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    if len(result) != n:
        print("Cycle detected! No topological sort possible.")
        return []
    return result


